local addonName, addon = ...

addon.readme = {
    { type = "header", value = "About" },
    { type = "text", value = "Taking advantage of the unique 3x exploration experience bonus that Earthen Dwarves receive, you can level quickly by exclusively flying around the world. This addon provides an optimized flying route that allows players to do this, offering a fresh and extremely efficient method of leveling." },
    { type = "header", value = "Key Features" },
    { type = "text", value = "|cFF87e6e8Exploration-Only Leveling|r - Capitalize on the 3x exploration XP bonus to level up without traditional questing or grinding." },
    { type = "text", value = "|cFF87e6e8Optimized Flying Routes|r - Follow carefully crafted paths designed for maximum efficiency." },
    { type = "text", value = "|cFF87e6e8Route Editor|r - Want to modify a route, make your own, or add notes to make your speedruns easier? No problem. Create, add, remove, reorder, rename, and annotate to your hearts content." },
    { type = "text", value = "|cFF87e6e8Save & Resume|r - Your run progress is saved automatically per character. If you log out mid-route, the addon will pick up exactly where you left off when you log back in." },
    { type = "text", value = "|cFF87e6e8Minimap Button|r - Click the minimap button to toggle the window, or right-click for quick access to segment navigation, abandoning a run, or resetting the window position. Drag the button to reposition it around the minimap." },
    { type = "text", value = "|cFF87e6e8Segment Navigation|r - Jump between segments within a route using Previous/Next Segment buttons, or use the Select dropdown to jump directly to any segment. Also accessible from the minimap button's right-click context menu." },
    { type = "text", value = "|cFF87e6e8Route Browser|r - Browse into route structures before starting a run. Drill down through segments to explore their children, then start a run from any level directly from the browser, the route editor, or the route viewer." },
    { type = "text", value = "|cFF87e6e8Map Overlay|r - When a run is active, the world map, zone map, and minimap all display the route's waypoints as connected dots with lines connecting their path. The entire route is projected onto continent views across zone boundaries, with the current waypoint highlighted in green and the most recently cleared waypoint shown faded. Dots scale smoothly with zoom, and hovering any dot shows its name and note. The minimap overlay updates in real time as you move, with lines to guide your path. Toggle on or off from Settings." },
    { type = "text", value = "|cFF87e6e8Waypoint Display Settings|r - Full control over TomTom and Blizzard pin waypoints. Each can be set to Auto, Enabled, or Disabled from the Settings panel. Auto mode intelligently detects installed addons and enables the appropriate display." },
    { type = "text", value = "|cFF87e6e8Automatic Discovery Tracking|r - The addon will automatically detect when you discover a zone and move to the next waypoint. Every discovery will be recorded and timestamped." },
    { type = "text", value = "|cFF87e6e8Keybinding Support|r - All navigation actions can be bound to hotkeys through the standard Key Bindings menu under \"Dystinct Earthen Skyriding\". Available bindings include Mark Node Discovered, Restore Previous Node, Next Segment, and Previous Segment." },
    { type = "text", value = "|cFF87e6e8Import/Export|r - Easily export and import routes as more leveling paths emerge. Your run logs can be exported too in CSV format." },
    { type = "header", value = "Commands" },
    { type = "text", value = "|cFF87e6e8/dyses|r — Toggle the main window" },
    { type = "text", value = "|cFF87e6e8/dyses show|r — Show the main window" },
    { type = "text", value = "|cFF87e6e8/dyses hide|r — Hide the main window" },
    { type = "text", value = "|cFF87e6e8/dyses reset|r — Reset the main window position to screen center" },
    { type = "text", value = "|cFF87e6e8/dyses minimap|r — Toggle the minimap button visibility" },
    { type = "text", value = "|cFF87e6e8/dyses help|r — Show available commands" },
    { type = "header", value = "Optional Dependencies" },
    { type = "text", value = "|cFF87e6e8TomTom|r - If installed, the addon can use it to provide a directional arrow to each waypoint. TomTom behavior can be configured in the Settings panel (Auto, Enabled, or Disabled)." },
    { type = "text", value = "|cFF87e6e8WaypointUI|r (Recommended) - Enhances the default Blizzard waypoint pin with improved visuals and tracking. The addon fully integrates with WaypointUI — when installed, pins are managed through its API for a seamless experience. WaypointUI works great alongside TomTom, and in Auto mode both will be active simultaneously." },
    { type = "text", value = "|cFF87e6e8FarmHUD|r - If installed, the minimap overlay will automatically appear on the FarmHUD when it is active, giving you a full-screen heads-up view of nearby route waypoints while flying." },
    { type = "text", value = "|cFF87e6e8Localization|r - If your client language is not English, you can still enjoy full functionality by installing LibBabble-SubZones-3.0 and Ace3. While the localization is limited to zone names, automatic detection of experience gained is functional and will use the appropriate translations wherever possible." },
    { type = "header", value = "Acknowledgements" },
    { type = "text", value = "The |cFF87e6e8Skyward Ascent|r community has been collaborating to optimize the Earthen skyriding leveling strategy and this addon is a result of these efforts. Special thanks to |cFF87e6e8Linaaa|r and the other absolute legends whose hard work has been instrumental to this project." },
}
